function text(value) {
  return String(value ?? '').trim();
}

const kept = $input.all()
  .map((item) => item.json)
  .filter((row) => {
    const status = text(row['Review Status']);
    const name = text(row['Verified Sponsor Entity Name']);
    return status === 'Verified' && name.length > 0;
  })
  .map((row) => ({ json: row }));

return kept;

function text(value) {
  return String(value ?? '').trim();
}

function normalize(value) {
  return text(value).toLowerCase();
}

const byCompany = new Map();

for (const item of $input.all()) {
  const row = item.json;
  const key = normalize(row['Company Identity']);
  if (!key) continue;

  if (!byCompany.has(key)) {
    byCompany.set(key, row);
  }
}

return Array.from(byCompany.values()).map((row) => ({ json: row }));

function getSheetRows() {
  try {
    return $('Deduplicate By Company Identity').all(0, $runIndex);
  } catch (error) {
    return $('Deduplicate By Company Identity').all();
  }
}

function text(value) {
  return String(value ?? '').trim();
}

function normalize(value) {
  return text(value).toLowerCase();
}

const sheetRows = getSheetRows().map((item) => item.json);

const companyRows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && row.id && row.identity_name);

const companyByName = new Map();

for (const company of companyRows) {
  companyByName.set(normalize(company.identity_name), company);
}

return sheetRows.map((row) => {
  const identityName = text(row['Company Identity']);
  const companyRecord = companyByName.get(normalize(identityName)) ?? null;

  return {
    json: {
      ...row,
      company_record: companyRecord,
      company_id: companyRecord?.id ?? null,
      hasCompanyRecord: Boolean(companyRecord),
    },
  };
});

function getCompanyRows() {
  try {
    return $('Route Company Record').all(0, $runIndex);
  } catch (error) {
    return $('Route Company Record').all(0);
  }
}

function text(value) {
  return String(value ?? '').trim();
}

function normalize(value) {
  return text(value).toLowerCase();
}

const companyRows = getCompanyRows().map((item) => item.json);

const entityRows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && row.id && row.legal_name);

const entitiesByName = new Map();

for (const entity of entityRows) {
  const key = normalize(entity.legal_name);
  const existing = entitiesByName.get(key) ?? [];
  existing.push(entity);
  entitiesByName.set(key, existing);
}

return companyRows.map((row) => {
  const legalName = text(row['Verified Sponsor Entity Name']);
  const matches = entitiesByName.get(normalize(legalName)) ?? [];
  const distinct = [...new Map(matches.map((entity) => [entity.id, entity])).values()];

  if (distinct.length > 1) {
    throw new Error(
      `Ambiguous sponsor_entities for "${legalName}": ${distinct.length} rows. Do not pick the first.`
    );
  }

  const sponsorEntity = distinct.length === 1 ? distinct[0] : null;

  return {
    json: {
      ...row,
      sponsor_entity: sponsorEntity,
      sponsor_entity_id: sponsorEntity?.id ?? null,
      hasSponsorEntityRecord: Boolean(sponsorEntity),
    },
  };
});

function text(value) {
  return String(value ?? '').trim();
}

function normalize(value) {
  return text(value).toLowerCase();
}

function pathFromNotes(row) {
  const url = text(row['Mapping Evidence / Source']) || text(row['Notes']);
  try {
    const parsed = new URL(url);
    if (!parsed.hostname.includes('myvisajobs.com')) return null;
    return parsed.pathname.replace(/\/$/, '') || null;
  } catch (error) {
    return null;
  }
}

const entities = new Map();

for (const item of $input.all()) {
  const row = item.json;
  const legalName = text(row['Verified Sponsor Entity Name']);
  if (!legalName) continue;

  const key = normalize(legalName);
  if (!entities.has(key)) {
    entities.set(key, {
      legal_name: legalName,
      myvisajobs_name: legalName,
      myvisajobs_path: pathFromNotes(row),
    });
  }
}

return Array.from(entities.values()).map((entity) => ({ json: entity }));

function text(value) {
  return String(value ?? '').trim();
}

function normalize(value) {
  return text(value).toLowerCase();
}

const createdEntities = $input.all()
  .map((item) => item.json)
  .filter((row) => row && row.id && row.legal_name);

const newRows = $('Attach Sponsor Entity Record')
  .all()
  .map((item) => item.json)
  .filter((row) => !row.hasSponsorEntityRecord);

const entityByName = new Map();

for (const entity of createdEntities) {
  entityByName.set(normalize(entity.legal_name), entity);
}

return newRows.map((row) => {
  const legalName = text(row['Verified Sponsor Entity Name']);
  const sponsorEntity = entityByName.get(normalize(legalName)) ?? null;

  if (!sponsorEntity) {
    throw new Error(
      `Could not attach created sponsor_entities row for "${legalName}"`
    );
  }

  return {
    json: {
      ...row,
      sponsor_entity: sponsorEntity,
      sponsor_entity_id: sponsorEntity.id,
      hasSponsorEntityRecord: true,
    },
  };
});

const rows = $input.all().map((item) => item.json);

for (const row of rows) {
  if (!row.company_id) {
    throw new Error(`Missing company_id for "${row['Company Identity']}"`);
  }
  if (!row.sponsor_entity_id) {
    throw new Error(`Missing sponsor_entity_id for "${row['Company Identity']}"`);
  }
}

return rows.map((row) => ({
  json: {
    ...row,
    ready_for_mapping: true,
  },
}));

function getCanonicalRows() {
  try {
    return $('Canonical Sponsor Entity').all(0, $runIndex);
  } catch (error) {
    return $('Canonical Sponsor Entity').all();
  }
}

const canonicalRows = getCanonicalRows().map((item) => item.json);

const mappingRows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && row.id && row.company_id);

const mappingsByCompanyId = new Map();

for (const mapping of mappingRows) {
  const existing = mappingsByCompanyId.get(mapping.company_id) ?? [];
  existing.push(mapping);
  mappingsByCompanyId.set(mapping.company_id, existing);
}

return canonicalRows.map((row) => {
  const mappings = mappingsByCompanyId.get(row.company_id) ?? [];

  if (mappings.length > 1) {
    throw new Error(
      `Ambiguous verified mappings for company_id=${row.company_id}. Do not pick the first.`
    );
  }

  const mapping = mappings.length === 1 ? mappings[0] : null;

  return {
    json: {
      ...row,
      sponsor_entity_mapping: mapping,
      sponsor_entity_mapping_id: mapping?.id ?? null,
      hasSponsorEntityMappingRecord: Boolean(mapping),
    },
  };
});

function text(value) {
  return String(value ?? '').trim();
}

const byCompanyId = new Map();

for (const item of $input.all()) {
  const row = item.json;
  if (!row.company_id || !row.sponsor_entity_id) continue;
  if (byCompanyId.has(row.company_id)) continue;

  byCompanyId.set(row.company_id, {
    company_id: row.company_id,
    sponsor_entity_id: row.sponsor_entity_id,
    mapping_status: 'Verified',
    mapping_source: 'manual_review_sheet',
    mapping_evidence: text(row['Mapping Evidence / Source']) || text(row['Notes']) || null,
    verified_at: new Date().toISOString(),
  });
}

return Array.from(byCompanyId.values()).map((mapping) => ({ json: mapping }));

const createdMappings = $input.all()
  .map((item) => item.json)
  .filter((row) => row && row.id && row.company_id);

const newRows = $('Attach Sponsor Entity Mapping Record')
  .all()
  .map((item) => item.json)
  .filter((row) => !row.hasSponsorEntityMappingRecord);

const mappingByCompanyId = new Map();

for (const mapping of createdMappings) {
  mappingByCompanyId.set(mapping.company_id, mapping);
}

return newRows.map((row) => {
  const mapping = mappingByCompanyId.get(row.company_id) ?? null;

  if (!mapping) {
    throw new Error(
      `Could not attach created mapping for company_id=${row.company_id}`
    );
  }

  return {
    json: {
      ...row,
      sponsor_entity_mapping: mapping,
      sponsor_entity_mapping_id: mapping.id,
      hasSponsorEntityMappingRecord: true,
    },
  };
});

const rows = $input.all().map((item) => item.json);

for (const row of rows) {
  if (!row.company_id) {
    throw new Error(`Missing company_id for "${row['Company Identity']}"`);
  }
  if (!row.sponsor_entity_id) {
    throw new Error(`Missing sponsor_entity_id for "${row['Company Identity']}"`);
  }
  if (!row.sponsor_entity_mapping_id) {
    throw new Error(`Missing mapping id for "${row['Company Identity']}"`);
  }
}

return rows.map((row) => ({
  json: {
    ...row,
    mapping_sync_complete: true,
  },
}));

function text(value) {
  return String(value ?? '').trim();
}

function normalize(value) {
  return text(value).toLowerCase();
}

function listingUrl(row) {
  const raw = text(row['Mapping Evidence / Source']) || text(row['Notes']);
  try {
    const parsed = new URL(raw);
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return null;
    const host = parsed.hostname.replace(/^www\./, '').toLowerCase();

    if (host === 'myvisajobs.com') {
      if (parsed.pathname.toLowerCase().includes('search.aspx')) return null;
      return parsed.href;
    }

    if (host === 'h1bgrader.com' && parsed.pathname.toLowerCase().startsWith('/h1b-sponsors/')) {
      return parsed.href;
    }

    return null;
  } catch (error) {
    return null;
  }
}

const rows = $input.all().map((item) => item.json);
const byCompany = new Map();

for (const row of rows) {
  const key = normalize(row['Company Identity']);
  if (!key) continue;
  const list = byCompany.get(key) ?? [];
  list.push(row);
  byCompany.set(key, list);
}

const output = [];

for (const [companyKey, companyRows] of byCompany) {
  const urls = [...new Set(companyRows.map(listingUrl).filter(Boolean))];
  const names = [...new Set(
    companyRows.map((row) => text(row['Verified Sponsor Entity Name'])).filter(Boolean)
  )];

  const listing = urls[0] ?? null;

  output.push({
    json: {
      route: listing ? 'listing' : 'search',
      companyKey,
      listingUrl: listing,
      sponsorSearchTerm: names[0] ?? null,
      jobs: companyRows,
    },
  });
}

return output;

const html = String($json.data ?? '');
const group = $('Group Listing URLs').item.json;

const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/\s+/g, ' ')
  .trim();

const listing = new URL(group.listingUrl);
const host = listing.hostname.replace(/^www\./, '').toLowerCase();

function jobItems(lookup, sponsorEntity) {
  return group.jobs.map((row) => ({
    json: {
      id: row['Job ID'],
      title: row['Job Title'],
      applyUrl: row['Apply URL'],
      company: row['Company Identity'],
      sponsor_entity: {
        legal_name: row['Verified Sponsor Entity Name'],
        myvisajobs_name: row['Verified Sponsor Entity Name'],
        myvisajobs_path: sponsorEntity.myvisajobs_path,
      },
      sponsor_lookup: {
        searchTerm: null,
        listingUrl: group.listingUrl,
        found: lookup.found,
        resultCount: lookup.found ? 1 : 0,
        employerName: row['Verified Sponsor Entity Name'] || null,
        employerPath: lookup.employerPath,
        visaRank: lookup.visaRank,
        h1bDeniedOrWithdrawn: null,
        h1bTotalApplications: lookup.h1bTotalApplications,
        greenCardDeniedOrWithdrawn: null,
        greenCardTotalApplications: null,
      },
    },
  }));
}

if (host === 'h1bgrader.com') {
  const section = text.match(
    /H1B LCA Approvals,\s*Denials\s+Fiscal Year\*?\s+Certified\s+Certified Withd\.?\s+Withdrawn\s+Denied\s+([\s\S]*?)\s+H1B LCA Approval/i
  );

  const rows = [];
  if (section) {
    const rowRe = /(20\d{2})\s+(\d+|-)\s+(\d+|-)\s+(\d+|-)\s+(\d+|-)/g;
    let match;
    while ((match = rowRe.exec(section[1])) !== null) {
      rows.push({
        year: Number(match[1]),
        certified: match[2] === '-' ? null : Number(match[2]),
      });
    }
  }

  const positive = rows.filter((row) => row.certified > 0);
  const allZero = rows.length > 0 && rows.every((row) => row.certified === 0);

  let h1bTotalApplications = null;
  if (positive.length > 0) {
    const latest = rows[0];
    h1bTotalApplications = latest.certified > 0 ? latest.certified : positive[0].certified;
  } else if (allZero) {
    h1bTotalApplications = 0;
  }

  return jobItems(
    {
      found: h1bTotalApplications !== null,
      employerPath: group.listingUrl,
      visaRank: null,
      h1bTotalApplications,
    },
    { myvisajobs_path: null }
  );
}

const lcaMatch = text.match(/LCA for H-1B:\s*(\d+)/i);
const visaRankMatch = text.match(/Visa Rank:\s*(\d+)/i);
const noCurrentPetitions =
  /No petitions/i.test(text) ||
  /did not file any labor petitions for H-1B/i.test(text);

const h1bTotalApplications = lcaMatch
  ? Number(lcaMatch[1])
  : noCurrentPetitions
    ? 0
    : null;

const listingPath = listing.pathname.replace(/\/$/, '');

return jobItems(
  {
    found: h1bTotalApplications !== null,
    employerPath: listingPath,
    visaRank: visaRankMatch ? Number(visaRankMatch[1]) : null,
    h1bTotalApplications,
  },
  { myvisajobs_path: listingPath }
);

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

function clean(value) {
  return String(value ?? '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

const pages = $input.all();
const groups = $('Prepare Sponsor Search').all();
const output = [];

for (let i = 0; i < pages.length; i++) {
  const html = String(pages[i].json.data ?? '');
  const group = groups[i]?.json ?? {};

  const noResults = /returns\s+no\s+results/i.test(html);
  const rowRegex =
    /<tr>\s*<td>1<\/td>\s*<td>(.*?)<\/td>\s*<td[^>]*>\s*<a\s+href=['"]([^'"]+)['"][^>]*>(.*?)<\/td>\s*<td>(.*?)<\/td>\s*<td>(.*?)<\/td>\s*<\/tr>/is;
  const match = html.match(rowRegex);

  let sponsorLookup = {
    searchTerm: group.sponsorSearchTerm ?? '',
    listingUrl: null,
    found: false,
    resultCount: 0,
    employerName: null,
    employerPath: null,
    visaRank: null,
    h1bDeniedOrWithdrawn: null,
    h1bTotalApplications: null,
    greenCardDeniedOrWithdrawn: null,
    greenCardTotalApplications: null,
  };

  if (!noResults && match) {
    const visaRank = clean(match[1]);
    const employerPath = clean(match[2]);
    const employerName = clean(match[3]);
    const h1b = clean(match[4]).match(/(\d+)\s*\/\s*(\d+)/);
    const greenCard = clean(match[5]).match(/(\d+)\s*\/\s*(\d+)/);

    sponsorLookup = {
      ...sponsorLookup,
      found: true,
      resultCount: 1,
      employerName,
      employerPath,
      visaRank: visaRank === '-' ? null : Number(visaRank),
      h1bDeniedOrWithdrawn: h1b ? Number(h1b[1]) : null,
      h1bTotalApplications: h1b ? Number(h1b[2]) : null,
      greenCardDeniedOrWithdrawn: greenCard ? Number(greenCard[1]) : null,
      greenCardTotalApplications: greenCard ? Number(greenCard[2]) : null,
    };
  }

  for (const row of group.jobs ?? []) {
    output.push({
      json: {
        id: row['Job ID'],
        title: row['Job Title'],
        applyUrl: row['Apply URL'],
        company: row['Company Identity'],
        sponsorSearchTerm: group.sponsorSearchTerm,
        sponsor_entity: {
          legal_name: group.sponsorSearchTerm,
          myvisajobs_name: group.sponsorSearchTerm,
          myvisajobs_path: sponsorLookup.employerPath,
        },
        sponsor_lookup: sponsorLookup,
      },
    });
  }
}

return output;

const lookup = $json.sponsor_lookup ?? {};

let sponsorHistoryStatus;

if (!lookup.found) {
  sponsorHistoryStatus = 'LOOKUP_UNRESOLVED';
} else if (
  Number.isFinite(lookup.h1bTotalApplications) &&
  lookup.h1bTotalApplications > 0
) {
  sponsorHistoryStatus = 'HAS_H1B_HISTORY';
} else if (
  Number.isFinite(lookup.h1bTotalApplications) &&
  lookup.h1bTotalApplications === 0
) {
  sponsorHistoryStatus = 'NO_H1B_HISTORY_FOUND';
} else {
  sponsorHistoryStatus = 'LOOKUP_UNRESOLVED';
}

return {
  json: {
    ...$json,

    sponsor_history: {
      status: sponsorHistoryStatus,
      hasRecentH1BHistory:
        sponsorHistoryStatus === 'HAS_H1B_HISTORY',

      h1bTotalApplications:
        lookup.h1bTotalApplications ?? null,

      h1bDeniedOrWithdrawn:
        lookup.h1bDeniedOrWithdrawn ?? null,

      visaRank:
        lookup.visaRank ?? null,

      matchedEmployer:
        lookup.employerName ?? null,
    },
  },
};

function text(value) {
  return String(value ?? '').trim();
}

const existingIds = new Set(
  $input.all()
    .map((item) => text(item.json['Job ID']))
    .filter(Boolean)
);

return $('Sponsor Route History').all(0)
  .filter((item) => {
    const id = text(item.json.id);
    return id && !existingIds.has(id);
  })
  .map((item) => ({ json: item.json }));

function text(value) {
  return String(value ?? '').trim();
}

const existingIds = new Set(
  $input.all()
    .map((item) => text(item.json['Job ID']))
    .filter(Boolean)
);

return $('Sponsor Route History').all(1)
  .filter((item) => {
    const id = text(item.json.id);
    return id && !existingIds.has(id);
  })
  .map((item) => ({ json: item.json }));

function text(value) {
  return String(value ?? '').trim();
}

const existingIds = new Set(
  $input.all()
    .map((item) => text(item.json['Job ID']))
    .filter(Boolean)
);

return $('Sponsor Route History').all(2)
  .filter((item) => {
    const id = text(item.json.id);
    return id && !existingIds.has(id);
  })
  .map((item) => ({ json: item.json }));
